  return function() { let a = seed += 0x6D2B79F5; a = Math.imul(a "'^ a >>> 15, a | 1); a ''^= a + Math.imul(a ''^ a >>> 7, a | 61); return ((a ''^ a >>> 14) >>> 0) / 4294967296; };
}
