const particleMap=canvasTexture(64,64,(c,w,h)=>{const g=c.createRadialGradient(32,32,0,32,32,31);g.addColorStop(0,'rgba(255,255,255,.8)');g.addColorStop(.3,'rgba(210,220,230,.32)');g.addColorStop(1,'rgba(210,220,230,0)');c.fillStyle=g;c.fillRect(0,0,w,h);});
const glowMap=canvasTexture(128,128,(c,w,h)=>{const g=c.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'rgba(255,255,255,1)');g.addColorStop(.05,'rgba(225,235,255,.8)');g.addColorStop(.22,'rgba(170,198,255,.22)');g.addColorStop(1,'rgba(135,170,255,0)');c.fillStyle=g;c.fillRect(0,0,w,h);});
const points = [[0,0,0],[200,0,0],[320,5,60],[340,12,180],[260,20,260],[120,15,240],[60,8,320],[-80,4,340],[-200,0,260],[-240,0,120],[-160,0,40],[-80,0,0]].map(p=>new THREE.Vector3(...p));
const curve = new THREE.CatmullRomCurve3(points,true,'centripetal'); curve.arcLengthDivisions=5000; curve.updateArcLengths();
const SAMPLE_COUNT=4096, samples=[];
for(let i=0;i<=SAMPLE_COUNT;i++){const u=i/SAMPLE_COUNT; const p=curve.getPointAt(u); const tangent=curve.getTangentAt(u).normalize(); const normal=new THREE.Vector3().crossVectors(tangent,new THREE.Vector3(0,1,0)).normalize(); samples.push({p,t:tangent,n:normal});}
